VALUES (NULL, NULL, 103020, 'Fallout 76', 'Fallout 76', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yc4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7y9.jpg', 'Fallout 76 is an online action role-playing game and the first multiplayer entry in the Fallout series. Set in 2102 in Appalachia, West Virginia, players control a resident of Vault 76 who ventures into the open world 25 years after a nuclear war. The game features exploration, questing, base building, and combat against mutated creatures and hostile factions. It can be played solo or cooperatively, with players sharing servers and engaging in trade or PvP combat.', 'https://www.igdb.com/games/fallout-76', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 5.6, 0, 9.51, '2026-11-20 01:06:03', '2026-11-20 01:06:03')
