VALUES (NULL, NULL, 343, 'Battlefield 3', 'Battlefield 3', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xbu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8ku.jpg', 'In Battlefield 3, players step into the role of the elite U.S. Marines. As the first boots on the ground, players will experience heart-pounding missions across diverse locations including Paris, Tehran and New York. As a U.S. Marine in the field, periods of tension and anticipation are punctuated by moments of complete chaos. As bullets whiz by, as walls crumble, as explosions force players to the ground, the battlefield feels more alive and interactive than ever before.', 'https://www.igdb.com/games/battlefield-3', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 8.2, 0, 1.01200000000000009e+01, '2026-11-20 01:06:03', '2026-11-20 01:06:03')
