VALUES (NULL, NULL, 1979, 'Battlefield 4', 'Battlefield 4', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1nmf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4gc.jpg', 'Battlefield 4 is the genre-defining action blockbuster created by Dice, and made from moments that blur the line between game and glory, moments found only in Battlefield. Go to Boot Camp to learn the basics of Battlefield 4''s engaging single player and intense multiplayer mode. Here you''ll also find intel on Levolution, Commander Mode, Naval Warfare and many more exciting game features.', 'https://www.igdb.com/games/battlefield-4', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, 7.8, 0, 1.01200000000000009e+01, '2026-11-20 01:06:03', '2026-11-20 01:06:03')
