VALUES (NULL, NULL, 166920, 'Easy Red 2', 'Easy Red 2', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co578s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar42p8.jpg', 'Fight in massive battles between infantry, armored vehicles, tanks, cannons and planes. Realistically manage your weapons and equipment, coordinate with your squad, and tactically navigate large, fully destructible open world maps. Experience the WW2 in single-player, PVP and Co-Op.', 'https://www.igdb.com/games/easy-red-2', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 10.01, '2026-11-20 01:06:03', '2026-11-20 01:06:03')
