VALUES (NULL, NULL, 428, 'Final Fantasy Tactics', 'Final Fantasy Tactics', 'game', 1997, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yx4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4707.jpg', 'Lead epic battles in a new FINAL FANTASY world. Betrayal and darker dealings await in Squaresoft''s game of war. Fight hundreds of battles across dangerous 3D terrain as an ancient blood feud awakens a deadlier foe.', 'https://www.igdb.com/games/final-fantasy-tactics', '["PlayStation 3", "PlayStation", "PlayStation Portable"]', NULL, 8.6, 0, 7.51, '2026-11-20 01:06:03', '2026-11-20 01:06:03')
