VALUES (NULL, NULL, 303161, 'Ancient Savo', 'Ancient Savo', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8th1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2ygo.jpg', 'Raise a family in the pristine woodlands of ancient Finland. Manage your homestead, craft tools and items, barter for goods, live off the land. Continue as your offspring, start new homesteads. Plan wisely to survive in the wilderness where cold, hunger and accidents are your enemies.', 'https://www.igdb.com/games/ancient-savo', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 9.53, '2026-11-20 01:06:03', '2026-11-20 01:06:03')
