VALUES (NULL, NULL, 578, 'Warhammer 40,000: Space Marine', 'Warhammer 40,000: Space Marine', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1tx9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3qna.jpg', 'In Warhammer 40,000 Space Marine you are Captain Titus, a Space Marine of the Ultramarines chapter and a seasoned veteran of countless battles.', 'https://www.igdb.com/games/warhammer-40-000-space-marine', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.6, 0, 8.36333333333333328e+00, '2026-11-19 20:56:22', '2026-11-20 01:06:03')
