VALUES (NULL, NULL, 18088, 'Insurgency: Sandstorm', 'Insurgency: Sandstorm', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9m28.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/rmduyabbeilf5dziyam3.jpg', 'Insurgency: Sandstorm is a team-based, tactical FPS based on lethal close quarters combat and objective-oriented multiplayer gameplay. Experience the intensity of modern combat where skill is rewarded, and teamwork wins the fight.', 'https://www.igdb.com/games/insurgency-sandstorm', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.6, 0, 1.11574999999999988e+01, '2026-11-19 20:56:22', '2026-11-20 01:06:03')
